using AcxiomCRM.Data;using AcxiomCRM.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Api;[ApiController,Route("api/opportunities"),Authorize] public class OpportunitiesApiController:ControllerBase{private readonly ApplicationDbContext _db;public OpportunitiesApiController(ApplicationDbContext db){_db=db;}[HttpGet]public async Task<IActionResult> Get()=>Ok(await _db.Opportunities.Include(x=>x.Customer).OrderByDescending(x=>x.CreatedDate).Select(x=>new{x.Id,x.OpportunityName,x.CustomerId,Customer=x.Customer==null?null:x.Customer.CustomerName,x.Amount,x.Stage,x.Probability,x.ExpectedCloseDate,x.Status,WeightedValue=x.Amount*x.Probability/100m}).ToListAsync());[HttpPost]public async Task<IActionResult> Create(Opportunity o){if(!ModelState.IsValid)return ValidationProblem(ModelState);if(o.Amount<=0)return BadRequest(new{message="Opportunity Amount must be greater than 0."});if(o.Probability<0||o.Probability>100)return BadRequest(new{message="Probability must be between 0 and 100."});if(o.Status=="Open"&&o.ExpectedCloseDate.Date<DateTime.Today)return BadRequest(new{message="Expected Close Date cannot be in the past."});o.Id=0;o.CreatedBy=User.Identity?.Name;_db.Opportunities.Add(o);await _db.SaveChangesAsync();return Created($"/api/opportunities/{o.Id}",new{id=o.Id,o.OpportunityName,o.Amount,o.Stage,o.Probability});}}
